// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testFuzz_property(uint256 _value, bytes memory _data) public {
        vm.assume(_value <= address(this).balance);
        Reverter reverter = new Reverter();
        vm.deal(address(c), _value);
        bool ok;
        vm.prank(c.owner());
        try c.sendMoney(address(reverter), _value, _data) { ok = true; } catch { ok = false; }
        assertTrue(!ok);
    }
}
contract Reverter { fallback() external payable { revert(); } }
